"""Regenerates src/table.rs from pymavlink's all.xml dialect.

    pip install pymavlink==2.4.50
    python tools/gen_table.py
"""
import pymavlink.dialects.v20.all as dialect

rows = sorted((k, c.crc_extra, c.unpacker.size, c.msgname) for k, c in dialect.mavlink_map.items())
out = [
    "//! MAVLink message table: id, CRC_EXTRA, maximum payload length and name.",
    "//!",
    "//! Generated by tools/gen_table.py from pymavlink 2.4.50 (`all.xml` dialect,",
    "//! which includes common, ardupilotmega, development and the vendor sets).",
    "//! Do not edit by hand.",
    "",
    "/// `(message id, CRC_EXTRA, maximum payload length, name)`, sorted by id.",
    "pub static MESSAGES: &[(u32, u8, u8, &str)] = &[",
]
out += [f'    ({i}, {c}, {n}, "{name}"),' for i, c, n, name in rows]
out.append("];")
with open("src/table.rs", "w", newline="") as f:
    f.write("\n".join(out) + "\n")
print(len(rows), "messages")
